import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { FaUserShield, FaList, FaCheckCircle, FaClock, FaExclamationCircle, FaTasks, FaChartLine } from 'react-icons/fa';

function AdminPanel() {
  const [user, setUser] = useState(null);
  const [issues, setIssues] = useState([]);
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    inProgress: 0,
    resolved: 0,
    critical: 0
  });

  useEffect(() => {
    const storedUser = localStorage.getItem('user');
    if (storedUser) {
      const parsedUser = JSON.parse(storedUser);
      setUser(parsedUser);

      if (parsedUser.role !== 'admin') {
        // Redirect non-admin users
        window.location.href = '/dashboard';
      }
    }

    const sampleIssues = [
      {
        id: 1,
        description: 'Broken classroom chair',
        category: 'Furniture',
        location: 'Room 101',
        status: 'Pending',
        priority: 'Medium',
        reportedBy: 'John Doe',
        reportedDate: '2026-06-15',
        assignedTo: null,
        timeline: [{ action: 'Issue Reported', time: '2026-06-15 10:30 AM' }]
      },
      {
        id: 2,
        description: 'Leaking toilet',
        category: 'Plumbing',
        location: 'Toilet Block A',
        status: 'In Progress',
        priority: 'High',
        reportedBy: 'Jane Smith',
        reportedDate: '2026-06-14',
        assignedTo: 'Rajesh Kumar',
        timeline: [
          { action: 'Issue Reported', time: '2026-06-14 09:15 AM' },
          { action: 'Assigned to Rajesh Kumar', time: '2026-06-14 11:00 AM' },
          { action: 'Status updated to In Progress', time: '2026-06-15 02:00 PM' }
        ]
      },
      {
        id: 3,
        description: 'Flickering light',
        category: 'Electrical',
        location: 'Library',
        status: 'Resolved',
        priority: 'Low',
        reportedBy: 'Mike Johnson',
        reportedDate: '2026-06-10',
        assignedTo: 'Suresh Patel',
        timeline: [
          { action: 'Issue Reported', time: '2026-06-10 11:00 AM' },
          { action: 'Assigned to Suresh Patel', time: '2026-06-11 09:00 AM' },
          { action: 'Status updated to In Progress', time: '2026-06-11 10:00 AM' },
          { action: 'Status updated to Resolved', time: '2026-06-12 04:30 PM' }
        ]
      },
      {
        id: 4,
        description: 'Damaged door handle',
        category: 'Furniture',
        location: 'Main Entrance',
        status: 'Pending',
        priority: 'Medium',
        reportedBy: 'Sarah Wilson',
        reportedDate: '2026-06-16',
        assignedTo: null,
        timeline: [{ action: 'Issue Reported', time: '2026-06-16 08:45 AM' }]
      },
      {
        id: 5,
        description: 'Cracked window glass',
        category: 'Classroom',
        location: 'Room 202',
        status: 'Pending',
        priority: 'Critical',
        reportedBy: 'Tom Brown',
        reportedDate: '2026-06-17',
        assignedTo: null,
        timeline: [{ action: 'Issue Reported', time: '2026-06-17 07:20 AM' }]
      }
    ];

    setIssues(sampleIssues);

    setStats({
      total: sampleIssues.length,
      pending: sampleIssues.filter(i => i.status === 'Pending').length,
      inProgress: sampleIssues.filter(i => i.status === 'In Progress').length,
      resolved: sampleIssues.filter(i => i.status === 'Resolved').length,
      critical: sampleIssues.filter(i => i.priority === 'Critical').length
    });
  }, []);

  const getStatusBadge = (status) => {
    const badges = {
      'Pending': 'status-pending',
      'In Progress': 'status-inprogress',
      'Resolved': 'status-resolved'
    };
    return badges[status] || 'status-pending';
  };

  const getPriorityBadge = (priority) => {
    const colors = {
      'Low': 'bg-success',
      'Medium': 'bg-info',
      'High': 'bg-warning',
      'Critical': 'bg-danger'
    };
    return colors[priority] || 'bg-info';
  };

  const handleUpdateStatus = (id, newStatus) => {
    setIssues(issues.map(issue => 
      issue.id === id ? {
        ...issue,
        status: newStatus,
        timeline: [...issue.timeline, {
          action: `Status updated to ${newStatus}`,
          time: new Date().toLocaleString()
        }]
      } : issue
    ));
  };

  const handleAssignTask = (id, assignee) => {
    setIssues(issues.map(issue => 
      issue.id === id ? {
        ...issue,
        assignedTo: assignee,
        timeline: [...issue.timeline, {
          action: `Assigned to ${assignee}`,
          time: new Date().toLocaleString()
        }]
      } : issue
    ));
  };

  if (!user || user.role !== 'admin') {
    return (
      <div className="py-5 text-center">
        <div className="alert alert-danger">
          <FaUserShield className="me-2" /> Admin access required
        </div>
        <Link to="/login" className="btn btn-custom">Go to Login</Link>
      </div>
    );
  }

  const staffList = ['Rajesh Kumar', 'Suresh Patel', 'Vikram Singh', 'Amit Sharma'];

  return (
    <div className="py-5">
      <div className="container">
        <div className="row mb-4">
          <div className="col-12">
            <h2 className="display-5">
              <FaUserShield className="me-3" /> Admin Panel
            </h2>
            <p className="text-muted">Manage school facilities and repair tasks</p>
          </div>
        </div>

        {/* Stats Cards */}
        <div className="row mb-5">
          <div className="col-md-2 mb-3">
            <div className="stat-card">
              <FaList style={{ fontSize: '2rem', color: '#667eea' }} />
              <h3>{stats.total}</h3>
              <p>Total Issues</p>
            </div>
          </div>
          <div className="col-md-2 mb-3">
            <div className="stat-card">
              <FaClock style={{ fontSize: '2rem', color: '#ffc107' }} />
              <h3>{stats.pending}</h3>
              <p>Pending</p>
            </div>
          </div>
          <div className="col-md-2 mb-3">
            <div className="stat-card">
              <FaTasks style={{ fontSize: '2rem', color: '#0d6efd' }} />
              <h3>{stats.inProgress}</h3>
              <p>In Progress</p>
            </div>
          </div>
          <div className="col-md-2 mb-3">
            <div className="stat-card">
              <FaCheckCircle style={{ fontSize: '2rem', color: '#198754' }} />
              <h3>{stats.resolved}</h3>
              <p>Resolved</p>
            </div>
          </div>
          <div className="col-md-2 mb-3">
            <div className="stat-card">
              <FaExclamationCircle style={{ fontSize: '2rem', color: '#dc3545' }} />
              <h3>{stats.critical}</h3>
              <p>Critical</p>
            </div>
          </div>
          <div className="col-md-2 mb-3">
            <div className="stat-card">
              <FaChartLine style={{ fontSize: '2rem', color: '#6f42c1' }} />
              <h3>{stats.resolved > 0 ? Math.round((stats.resolved / stats.total) * 100) : 0}%</h3>
              <p>Resolution Rate</p>
            </div>
          </div>
        </div>

        {/* Quick Actions */}
        <div className="row mb-5">
          <div className="col-12">
            <h4 className="mb-3">Admin Actions</h4>
          </div>
          <div className="col-md-3 mb-3">
            <Link to="/admin/reports" className="btn btn-custom btn-lg w-100">
              <FaChartLine className="me-2" /> Generate Reports
            </Link>
          </div>
          <div className="col-md-3 mb-3">
            <Link to="/admin/staff" className="btn btn-outline-primary btn-lg w-100">
              <FaUserShield className="me-2" /> Manage Staff
            </Link>
          </div>
          <div className="col-md-3 mb-3">
            <Link to="/admin/users" className="btn btn-outline-info btn-lg w-100">
              <FaList className="me-2" /> Manage Users
            </Link>
          </div>
          <div className="col-md-3 mb-3">
            <Link to="/admin/schedule" className="btn btn-outline-warning btn-lg w-100">
              <FaClock className="me-2" /> Repair Schedule
            </Link>
          </div>
        </div>

        {/* Issues Management */}
        <div className="row mb-3">
          <div className="col-12">
            <h4>Issues Management</h4>
          </div>
        </div>

        <div className="row">
          <div className="col-12">
            <div className="table-custom">
              <table className="table table-hover">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Description</th>
                    <th>Category</th>
                    <th>Location</th>
                    <th>Priority</th>
                    <th>Status</th>
                    <th>Assigned To</th>
                    <th>Reported By</th>
                    <th>Date</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {issues.map((issue) => (
                    <tr>
                      <td><strong>#{issue.id}</strong></td>
                      <td>{issue.description}</td>
                      <td>{issue.category}</td>
                      <td>{issue.location}</td>
                      <td><span className={`badge ${getPriorityBadge(issue.priority)}`}>{issue.priority}</span></td>
                      <td><span className={getStatusBadge(issue.status)}>{issue.status}</span></td>
                      <td>{issue.assignedTo || <span className="text-muted">Not assigned</span>}</td>
                      <td>{issue.reportedBy}</td>
                      <td>{issue.reportedDate}</td>
                      <td>
                        <div className="d-flex gap-1">
                          {issue.status === 'Pending' && (
                            <>
                              <select
                                className="form-select form-select-sm"
                                style={{ width: '120px' }}
                                onChange={(e) => {
                                  if (e.target.value) handleAssignTask(issue.id, e.target.value);
                                }}
                                value={issue.assignedTo || ''}
                              >
                                <option value="">Assign</option>
                                {staffList.map(staff => (
                                  <option key={staff} value={staff}>{staff}</option>
                                ))}
                              </select>
                              <button
                                className="btn btn-sm btn-success"
                                onClick={() => handleUpdateStatus(issue.id, 'In Progress')}
                              >
                                Start
                              </button>
                            </>
                          )}
                          {issue.status === 'In Progress' && (
                            <button
                              className="btn btn-sm btn-primary"
                              onClick={() => handleUpdateStatus(issue.id, 'Resolved')}
                            >
                              Complete
                            </button>
                          )}
                          <Link
                            to={`/issue/${issue.id}`}
                            className="btn btn-sm btn-outline-secondary"
                          >
                            View
                          </Link>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default AdminPanel;
